class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        self._balances: dict[str, float] = {m: 0.0 for m in self.members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        if payer not in self._balances:
            raise ValueError(f"Unknown payer: {payer}")
        if participants is None:
            participants = self.members
        if not participants:
            raise ValueError("No participants")
        for p in participants:
            if p not in self._balances:
                raise ValueError(f"Unknown participant: {p}")
        if amount <= 0:
            raise ValueError("Amount must be positive")

        share = amount / len(participants)
        self._balances[payer] += amount
        for p in participants:
            self._balances[p] -= share

    def balances(self) -> dict[str, float]:
        # Round to avoid floating point noise
        return {m: round(v, 2) for m, v in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        # Work on copies, rounded to cents
        credits = []  # (name, amount) with positive balance
        debts = []    # (name, amount) with negative balance
        for m, v in self._balances.items():
            v = round(v, 2)
            if v > 0:
                credits.append([m, v])
            elif v < 0:
                debts.append([m, -v])

        credits.sort(key=lambda x: -x[1])
        debts.sort(key=lambda x: -x[1])

        payments: list[tuple[str, str, float]] = []
        i = j = 0
        while i < len(debts) and j < len(credits):
            debtor, owe = debts[i]
            creditor, owed = credits[j]
            pay = min(owe, owed)
            if pay >= 1.0:
                payments.append((debtor, creditor, round(pay, 2)))
            owe -= pay
            owed -= pay
            if owe <= 0.005:
                i += 1
            else:
                debts[i][1] = owe
            if owed <= 0.005:
                j += 1
            else:
                credits[j][1] = owed

        return payments
